    int used = 0;

    for (int i = 0; i < m && used < n - 1; i++) {
        if (union_set(dsu, edges[i].u, edges[i].v)) {
            total_weight += edges[i].w;
            used++;
        }
    }

    printf("%lld\n", total_weight);

    free(edges);
    free(dsu);
    return 0;
}

